import { MakeLogicType, afterMount, connect, kea, path } from 'kea'
import { loaders } from 'kea-loaders'

import { projectLogic } from 'scenes/projectLogic'

import { workflowNodesList } from 'products/workflows/frontend/generated/api'
import type { WorkflowNodeApi } from 'products/workflows/frontend/generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface workflowNodesLogicValues {
    currentProjectId: number | null // projectLogic
    workflowNodes: WorkflowNodeApi[] | null
    workflowNodesLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface workflowNodesLogicActions {
    loadWorkflowNodes: () => any
    loadWorkflowNodesFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadWorkflowNodesSuccess: (
        workflowNodes: WorkflowNodeApi[] | null,
        payload?: any
    ) => {
        workflowNodes: WorkflowNodeApi[] | null
        payload?: any
    }
}

export type workflowNodesLogicType = MakeLogicType<workflowNodesLogicValues, workflowNodesLogicActions>

export const workflowNodesLogic = kea<workflowNodesLogicType>([
    path(['products', 'workflows', 'frontend', 'Workflows', 'hogflows', 'steps', 'workflowNodesLogic']),
    connect(() => ({
        values: [projectLogic, ['currentProjectId']],
    })),
    loaders(({ values }) => ({
        workflowNodes: [
            null as WorkflowNodeApi[] | null,
            {
                loadWorkflowNodes: async () => {
                    if (!values.currentProjectId) {
                        return null
                    }
                    return await workflowNodesList(String(values.currentProjectId))
                },
            },
        ],
    })),
    afterMount(({ actions }) => {
        actions.loadWorkflowNodes()
    }),
])
